import sys

def klengthpref(arr, n, k, str_val):
    target_prefix = str_val[:k]
    count = 0
    for s in arr:
        if len(s) >= k and s[:k] == target_prefix:
            count += 1
    return count

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
        arr = []
        for _ in range(n):
            arr.append(next(iterator))
        k = int(next(iterator))
        str_val = next(iterator)

        result = klengthpref(arr, n, k, str_val)
        print(result)
    except StopIteration:
        pass

if __name__ == "__main__":
    main()
